import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/firebase-admin";
import { withAgentAuth } from "@/lib/with-agent-auth";
import {
  parse,
  startOfDay,
  setHours,
  setMinutes,
  addMinutes,
  format,
} from "date-fns";

type RouteCtx = { params: Promise<{ id: string }> };

const CLIENT_ID_RE = /^[a-zA-Z0-9_-]+$/;

function sumarMinutos(hora: string, minutos: number): string {
  const date = new Date(2000, 0, 1);
  const [h, m] = hora.split(":").map(Number);
  const t = setMinutes(setHours(startOfDay(date), h), m);
  return format(addMinutes(t, minutos), "HH:mm");
}

export const PATCH = withAgentAuth(async (req: NextRequest, ctx?) => {
  const { id } = await (ctx as RouteCtx).params;

  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Body invalido" }, { status: 400 });
  }

  const clientId = body.clientId as string;
  if (!clientId || !CLIENT_ID_RE.test(clientId)) {
    return NextResponse.json({ error: "clientId invalido" }, { status: 400 });
  }

  // Leer appointment
  const appointmentRef = db.collection("appointments").doc(id);
  const appointmentSnap = await appointmentRef.get();

  if (!appointmentSnap.exists) {
    return NextResponse.json(
      { success: false, error: "Turno no encontrado" },
      { status: 404 }
    );
  }

  const appointment = appointmentSnap.data()!;

  if (appointment.clientId !== clientId) {
    return NextResponse.json({ error: "No autorizado" }, { status: 403 });
  }

  if (appointment.status === "cancelled") {
    return NextResponse.json(
      { success: false, error: "Turno ya cancelado" },
      { status: 409 }
    );
  }

  // Leer config para obtener buffer
  const configSnap = await db.collection("config").doc(clientId).get();
  const rules = (configSnap.exists ? configSnap.data()?.businessRules : {}) || {};
  const bufferMinutes =
    typeof rules.bufferMinutes === "number" ? rules.bufferMinutes : 10;

  const staffId = appointment.staffId || "";
  const dateStr = appointment.date || "";
  const time = appointment.time || "";
  const duration = appointment.duration || 30;

  // Transaccion: cancelar appointment + limpiar manifest
  const manifestId = `${clientId}_${staffId}_${dateStr}`;
  const manifestRef = db.collection("daily_manifests").doc(manifestId);

  try {
    await db.runTransaction(async (transaction) => {
      // Actualizar status del appointment
      transaction.update(appointmentRef, { status: "cancelled" });

      // Limpiar intervalo del manifest
      const manifestSnap = await transaction.get(manifestRef);
      if (!manifestSnap.exists) return;

      const intervals: { start: string; end: string }[] =
        manifestSnap.data()?.intervals ?? [];

      const endWithBuffer = sumarMinutos(time, duration + bufferMinutes);
      const filtered = intervals.filter(
        (inv) => !(inv.start === time && inv.end === endWithBuffer)
      );

      if (filtered.length < intervals.length) {
        transaction.update(manifestRef, { intervals: filtered });
      }
    });

    return NextResponse.json({ success: true });
  } catch (err) {
    console.error("[appointments/cancel] transaction error:", err);
    return NextResponse.json(
      { success: false, error: "Error al cancelar turno" },
      { status: 500 }
    );
  }
});

import { withOwner } from "@/lib/auth";
import { db } from "@/lib/firebase-admin";
import { NextResponse } from "next/server";
import { FieldValue } from "firebase-admin/firestore";
import type { ProspectFollowUpStatus, ProspectChannel } from "@/types";

const COLLECTION = "hub_prospect_followups";

function computeFollowUpDue(
  status: ProspectFollowUpStatus,
  webSentAt?: string
): string | null {
  if (status !== "web_sent" || !webSentAt) return null;
  const sent = new Date(webSentAt);
  const day3 = new Date(sent);
  day3.setDate(day3.getDate() + 3);
  return day3.toISOString();
}

export const GET = withOwner(async (req) => {
  const { searchParams } = new URL(req.url);
  const statusFilter = searchParams.get("status");
  const pendingOnly = searchParams.get("pending") === "true";

  let query: FirebaseFirestore.Query = db.collection(COLLECTION);

  if (statusFilter) {
    query = query.where("status", "==", statusFilter);
  }

  const snap = await query.orderBy("updatedAt", "desc").get();
  const now = new Date();

  const prospects = snap.docs.map((doc) => {
    const data = doc.data();
    return {
      id: doc.id,
      ...data,
      createdAt: data.createdAt?.toDate?.()?.toISOString?.() ?? data.createdAt,
      updatedAt: data.updatedAt?.toDate?.()?.toISOString?.() ?? data.updatedAt,
    } as Record<string, any> & { id: string };
  });

  if (pendingOnly) {
    const pending = prospects.filter((p) => {
      if (!p.followUpDue) return false;
      return new Date(p.followUpDue as string) <= now &&
        !["paid", "not_interested"].includes(p.status as string);
    });
    return NextResponse.json(pending);
  }

  return NextResponse.json(prospects);
});

export const POST = withOwner(async (req) => {
  const body = await req.json();
  const {
    clientId,
    businessName,
    contactName,
    contactPhone,
    niche,
    deployUrl,
    status = "web_created",
  } = body;

  if (!businessName) {
    return NextResponse.json(
      { error: "businessName es requerido" },
      { status: 400 }
    );
  }

  const now = new Date().toISOString();

  const doc = {
    clientId: clientId || null,
    businessName,
    contactName: contactName || null,
    contactPhone: contactPhone || null,
    niche: niche || null,
    deployUrl: deployUrl || null,
    status,
    statusHistory: [{ status, date: now }],
    webSentAt: null,
    webSentVia: null,
    followUpDue: null,
    lastContactAt: null,
    createdAt: FieldValue.serverTimestamp(),
    updatedAt: FieldValue.serverTimestamp(),
  };

  const ref = await db.collection(COLLECTION).add(doc);
  return NextResponse.json({ id: ref.id });
});

export const PATCH = withOwner(async (req) => {
  const body = await req.json();
  const { id, status, note, channel, webSentAt } = body as {
    id: string;
    status?: ProspectFollowUpStatus;
    note?: string;
    channel?: ProspectChannel;
    webSentAt?: string;
  };

  if (!id) {
    return NextResponse.json({ error: "id requerido" }, { status: 400 });
  }

  const ref = db.collection(COLLECTION).doc(id);
  const snap = await ref.get();

  if (!snap.exists) {
    return NextResponse.json({ error: "No encontrado" }, { status: 404 });
  }

  const current = snap.data()!;
  const updates: Record<string, unknown> = {
    updatedAt: FieldValue.serverTimestamp(),
  };

  if (status) {
    updates.status = status;
    const now = new Date().toISOString();
    updates.statusHistory = [
      ...(current.statusHistory || []),
      { status, date: now, note: note || undefined },
    ];
    updates.lastContactAt = now;

    if (status === "web_sent") {
      const sentAt = webSentAt || now;
      updates.webSentAt = sentAt;
      updates.webSentVia = channel || null;
      updates.followUpDue = computeFollowUpDue("web_sent", sentAt);
    }

    if (status === "paid" || status === "not_interested") {
      updates.followUpDue = null;
    }
  }

  await ref.update(updates);
  return NextResponse.json({ ok: true });
});

export const DELETE = withOwner(async (req) => {
  const { id } = await req.json();
  if (!id) {
    return NextResponse.json({ error: "id requerido" }, { status: 400 });
  }
  await db.collection(COLLECTION).doc(id).delete();
  return NextResponse.json({ ok: true });
});

import { NextRequest, NextResponse } from "next/server";
import { randomUUID } from "crypto";
import { withOwner } from "@/lib/auth";
import { getStorageBucket } from "@/lib/firebase-admin";

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB
const MAX_FILES = 20;
const ALLOWED_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "image/avif",
  "image/x-icon",
  "image/vnd.microsoft.icon",
  "application/json",
]);

/** Fallback MIME detection by extension — webkitGetAsEntry() on Windows
 *  often produces File objects with an empty `type` string. */
const EXT_TO_MIME: Record<string, string> = {
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".png": "image/png",
  ".webp": "image/webp",
  ".gif": "image/gif",
  ".avif": "image/avif",
  ".json": "application/json",
  ".ico": "image/x-icon",
};

function resolveContentType(file: File): string {
  if (file.type && file.type !== "application/octet-stream") return file.type;
  const ext = file.name.slice(file.name.lastIndexOf(".")).toLowerCase();
  return EXT_TO_MIME[ext] || "";
}

function sanitizeFilename(name: string): string {
  return name
    .replace(/[^a-zA-Z0-9._-]/g, "_")
    .replace(/_{2,}/g, "_")
    .slice(0, 80);
}

export const POST = withOwner(async (req, _session, ctx) => {
  const { clientId } = await ctx.params;

  if (!/^[a-zA-Z0-9_-]+$/.test(clientId)) {
    return NextResponse.json({ error: "clientId invalido" }, { status: 400 });
  }

  let formData: FormData;
  try {
    formData = await req.formData();
  } catch {
    return NextResponse.json({ error: "Se esperaba multipart/form-data" }, { status: 400 });
  }

  const files = formData.getAll("file").filter((f): f is File => f instanceof File);

  if (files.length === 0) {
    return NextResponse.json({ error: "No se enviaron archivos" }, { status: 400 });
  }

  if (files.length > MAX_FILES) {
    return NextResponse.json({ error: `Maximo ${MAX_FILES} archivos por request` }, { status: 400 });
  }

  const bucket = getStorageBucket();
  const urls: string[] = [];
  const errors: string[] = [];

  for (const file of files) {
    const contentType = resolveContentType(file);

    if (!contentType || !ALLOWED_TYPES.has(contentType)) {
      errors.push(`${file.name}: tipo no permitido (${file.type || "vacío"} → ${contentType || "desconocido"})`);
      continue;
    }

    if (file.size > MAX_FILE_SIZE) {
      errors.push(`${file.name}: excede 5MB`);
      continue;
    }

    const timestamp = Date.now();
    const safeName = sanitizeFilename(file.name);
    const storagePath = `clients/${clientId}/images/${timestamp}-${safeName}`;

    try {
      const buffer = Buffer.from(await file.arrayBuffer());
      const bucketFile = bucket.file(storagePath);

      await bucketFile.save(buffer, {
        metadata: {
          contentType,
          cacheControl: "public, max-age=31536000",
        },
      });

      // Use Firebase download token instead of makePublic() — works regardless
      // of bucket access control settings (Uniform or Fine-grained).
      const token = randomUUID();
      await bucketFile.setMetadata({
        metadata: { firebaseStorageDownloadTokens: token },
      });

      const publicUrl = `https://firebasestorage.googleapis.com/v0/b/${bucket.name}/o/${encodeURIComponent(storagePath)}?alt=media&token=${token}`;
      urls.push(publicUrl);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`[upload] Error subiendo ${file.name}:`, msg);
      errors.push(`${file.name}: ${msg}`);
    }
  }

  if (urls.length === 0 && errors.length > 0) {
    return NextResponse.json({ error: errors.join("; ") }, { status: 400 });
  }

  return NextResponse.json({ urls, errors: errors.length > 0 ? errors : undefined });
});

import type { BookingTier } from "@/types";

export type PlanType = "solo_web" | "web_crm" | "completo" | "base" | "pro" | "enterprise";

export const SOLO_WEB_AMOUNT = 480;
export const PLAN_AMOUNT = 770;
export const WEB_CRM_AMOUNT = PLAN_AMOUNT;
export const COMPLETO_AMOUNT = PLAN_AMOUNT;
export const CURRENCY = "ILS";

export const TIER_PRICING: Record<BookingTier, number> = {
  base: 770,
  pro: 960,
  enterprise: 1270,
};

export const TIER_LIMITS: Record<BookingTier, number> = {
  base: 100,
  pro: 300,
  enterprise: Infinity,
};

export const TIER_LABELS: Record<BookingTier, string> = {
  base: "Base",
  pro: "Pro",
  enterprise: "Enterprise",
};

export const TIER_ORDER: BookingTier[] = ["base", "pro", "enterprise"];

export function getNextTier(current: BookingTier): BookingTier | null {
  const idx = TIER_ORDER.indexOf(current);
  return idx < TIER_ORDER.length - 1 ? TIER_ORDER[idx + 1] : null;
}

export function getTierAmount(tier: BookingTier): number {
  return TIER_PRICING[tier];
}

export function getPlanAmount(plan?: PlanType): number {
  if (plan === "solo_web") return SOLO_WEB_AMOUNT;
  if (plan === "pro") return TIER_PRICING.pro;
  if (plan === "enterprise") return TIER_PRICING.enterprise;
  return PLAN_AMOUNT;
}

/** @deprecated — use PLAN_AMOUNT */
export const INITIAL_AMOUNT = PLAN_AMOUNT;
/** @deprecated — use PLAN_AMOUNT */
export const RECURRING_AMOUNT = PLAN_AMOUNT;
/** @deprecated */
export function getPaymentAmount(_isInitial: boolean): number {
  return PLAN_AMOUNT;
}
